import {withStableView} from './view-stability.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=value=>Number.isSafeInteger(value)?value.toLocaleString('zh-CN'):'—';
const date=value=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'medium',timeStyle:'short'}).format(new Date(value));
export function mountCreditRedemption({container,fetchImpl}={}){
 const doc=container.ownerDocument,win=doc.defaultView,route=win.location.hash,controllers=new Set();let disposed=false,userId=null,busy=false,page=1,total=0,historySequence=0;
 const live=()=>!disposed&&container.isConnected&&win.location.hash===route;
 if(!doc.querySelector('link[data-credit-redemption-style]')){const style=doc.createElement('link');style.rel='stylesheet';style.href='/workspace/credit-redemption.css';style.dataset.creditRedemptionStyle='';doc.head.append(style);}
 const $=selector=>container.querySelector(selector),dispose=()=>{disposed=true;controllers.forEach(controller=>controller.abort());controllers.clear();win.removeEventListener('hashchange',leave);win.removeEventListener('pagehide',dispose);};
 const leave=()=>{if(win.location.hash!==route)dispose();};win.addEventListener('hashchange',leave);win.addEventListener('pagehide',dispose,{once:true});
 container.innerHTML=`<div class="credit-redeem-layout"><section class="credit-redeem-main"><span class="credit-redeem-kicker">科研积分兑换</span><h2>让每一份支持，即刻到账</h2><p class="credit-redeem-intro">输入官方活动兑换码，兑换科研积分。</p><form data-credit-redeem-form><label for="credit-redemption-code">积分兑换码</label><div class="credit-redeem-input-row"><input id="credit-redemption-code" name="code" maxlength="100" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="PK-XXXX-XXXX-XXXX-XXXX-XXXX-XXXX" disabled required><button class="btn primary" type="submit" disabled>立即兑换</button></div><p class="credit-redeem-hint">支持粘贴完整兑换码，每个码仅可成功兑换一次。</p></form><div data-credit-redeem-message role="status" aria-live="polite">正在读取账户信息…</div><div data-credit-redeem-success hidden></div></section><aside class="credit-redeem-balance"><span>当前可用积分</span><strong data-credit-redeem-available>—</strong><p>账户余额 <b data-credit-redeem-balance>—</b> · 任务预占 <b data-credit-redeem-held>—</b></p><a href="#membership">查看权益与积分流水 →</a><div><h3>兑换即入账</h3><p>兑换成功后，可直接用于已开放的积分计费服务。到账记录将在当前账户保留。</p><a href="#membership/pricing">查看服务价目表 →</a></div></aside></div><section class="credit-redeem-history"><header><div><h3>我的兑换记录</h3><p>仅显示当前账户已成功到账的记录。</p></div><button type="button" class="btn secondary" data-credit-history-reload disabled>刷新记录</button></header><div data-credit-redeem-history><p>正在读取兑换记录…</p></div><div class="credit-redeem-pagination" data-credit-history-pages hidden><button type="button" class="btn secondary" data-credit-history-page="previous">上一页</button><span data-credit-history-page-label></span><button type="button" class="btn secondary" data-credit-history-page="next">下一页</button></div></section>`;
 const message=(text,error=false)=>{if(live()){const node=$('[data-credit-redeem-message]');node.textContent=text;node.classList.toggle('is-error',error);}};
 const controls=()=>{if(!live())return;$('[name=code]').disabled=busy||!userId;$('[type=submit]').disabled=busy||!userId;$('[type=submit]').textContent=busy?'正在兑换…':'立即兑换';$('[data-credit-history-reload]').disabled=busy||!userId;};
 function balance(value){if(![value?.balance,value?.available,value?.held].every(n=>Number.isSafeInteger(n)&&n>=0)||value.balance-value.held!==value.available)throw Error('积分记录暂不可用，请刷新后重试');for(const [key,selector]of [['available','available'],['balance','balance'],['held','held']])$('[data-credit-redeem-'+selector+']').textContent=number(value[key]);}
 async function request(path,body){const controller=new win.AbortController();controllers.add(controller);let timedOut=false;const timer=win.setTimeout(()=>{timedOut=true;controller.abort();},15000);try{const response=await (fetchImpl||win.fetch.bind(win))('/api'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:{...(body===undefined?{}:{'Content-Type':'application/json'}),...(userId?{'X-PaperKnow-User':userId}:{})},...(body===undefined?{}:{body:JSON.stringify(body)}),signal:controller.signal});const value=await response.json();if(!live())throw new win.DOMException('页面已切换','AbortError');if(!response.ok)throw Object.assign(Error(value.error||'暂时无法兑换，请稍后重试'),{status:response.status,code:value.code});return value;}catch(error){if(timedOut)throw Error('请求超时，可用原兑换码重试核对，不会重复到账。');if(error.status||error.name==='AbortError'||error.code)throw error;throw Error('暂时无法确认请求结果，请稍后用原兑换码重试。');}finally{win.clearTimeout(timer);controllers.delete(controller);}}
 async function fresh(){const value=await request('/auth/me');if(!value.user?.id||userId&&value.user.id!==userId)throw Object.assign(Error('登录账户已变化，请重新打开积分兑换页面'),{code:'ACCOUNT_CHANGED'});return value.user;}
 function failure(error){if(!live()||error.name==='AbortError')return;if(error.code==='ACCOUNT_CHANGED'||error.status===401||error.status===403){userId=null;for(const field of ['available','balance','held'])$('[data-credit-redeem-'+field+']').textContent='—';$('[data-credit-redeem-history]').replaceChildren();$('[data-credit-redeem-success]').hidden=true;$('[name=code]').value='';message(error.status===401?'请先登录后使用积分兑换码。':error.message,true);if(error.status===401)$('[data-credit-redeem-message]').insertAdjacentHTML('beforeend',' <a href="/auth.html?mode=login&next=%2Fworkspace.html%23membership%2Fredeem">前往登录 →</a>');}else message(error.message||'请求暂未完成，可用原兑换码重试，不会重复到账。',true);controls();}
 async function history(){const ticket=++historySequence,requestedPage=page,value=await request('/credits/redemptions?page='+requestedPage+'&pageSize=5');await fresh();if(!live()||ticket!==historySequence)return;if(!Array.isArray(value.items)||!Number.isSafeInteger(value.total)||value.total<0||value.items.some(row=>typeof row.codeHint!=='string'||!Number.isSafeInteger(row.amount)||row.amount<=0||!Number.isFinite(Date.parse(row.createdAt))))throw Error('兑换记录格式不完整，请稍后刷新');total=value.total;balance(value.credits);withStableView(container.closest('.dashboard')||container,()=>{$('[data-credit-redeem-history]').innerHTML=value.items.length?`<div class="credit-redeem-records">${value.items.map(row=>`<article><div><strong>积分兑换成功</strong><span>${esc(row.codeHint)}</span></div><time>${esc(date(row.createdAt))}</time><b>+${number(row.amount)} 积分</b></article>`).join('')}</div>`:'<div class="credit-redeem-empty">暂无兑换记录，成功兑换后将在这里显示。</div>';const pages=$('[data-credit-history-pages]');pages.hidden=total<=5;$('[data-credit-history-page-label]').textContent=page+' / '+Math.max(1,Math.ceil(total/5));$('[data-credit-history-page="previous"]').disabled=page<=1;$('[data-credit-history-page="next"]').disabled=page*5>=total;});}
 async function submit(event){event.preventDefault();if(busy||!userId||!live())return;const code=$('[name=code]').value.trim();if(!code){message('请先输入完整兑换码',true);return;}busy=true;controls();message('正在兑换，请稍候…');$('[data-credit-redeem-success]').hidden=true;try{await fresh();const value=await request('/credits/redeem',{code});await fresh();if(!live())return;if(!Number.isSafeInteger(value.redemption?.amount)||value.redemption.amount<=0||typeof value.alreadyRedeemed!=='boolean')throw Error('兑换结果尚未确认，请用原码重试核对');balance(value.credits);const result=$('[data-credit-redeem-success]');result.hidden=false;result.innerHTML=`<span aria-hidden="true">✓</span><div><h3>${value.alreadyRedeemed?'该兑换码已在本账户到账':'兑换成功'}</h3><p>${value.alreadyRedeemed?'本次未重复增加积分，原到账金额为':'已为当前账户增加'} <strong>${number(value.redemption.amount)} 积分</strong>。</p></div>`;$('[name=code]').value='';message('到账结果已确认，可在下方查看记录。');page=1;try{await history();}catch{if(live())message('积分已到账，兑换记录暂未刷新，请点击“刷新记录”。');}}catch(error){failure(error);}finally{busy=false;controls();}}
 $('[data-credit-redeem-form]').addEventListener('submit',event=>void submit(event));
 $('[data-credit-history-reload]').addEventListener('click',()=>{if(!busy)void history().catch(failure);});
 container.querySelectorAll('[data-credit-history-page]').forEach(button=>button.addEventListener('click',()=>{if(busy)return;page+=button.dataset.creditHistoryPage==='next'?1:-1;page=Math.min(Math.max(page,1),Math.max(1,Math.ceil(total/5)));void history().catch(failure);}));
 const ready=(async()=>{try{const user=await fresh();if(!live())return;userId=user.id;await history();if(live()){message('');controls();}}catch(error){failure(error);}})();
 return{ready,dispose};
}
